	if err := r.DB.Where("multi_group_id = ?", *multiGroupID).Order("created_at DESC").Find(&bookings).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch appointment bookings for multiGroupID %s: %v", *multiGroupID, err)
	}
	return bookings, nil
